import { type JsonRecord, check } from "./core";

/** Business configuration lives in the project's publication rules, never in executor state. */
export function readAccounts(markdown: string): JsonRecord {
  const section = markdown.split(/^## 发布账号配置\s*$/mu)[1]?.split(/^## /mu)[0];
  const json = section?.match(/```json\s*\n([\s\S]*?)\n```/u)?.[1];
  check(json, "发布规范缺少“发布账号配置”节的 JSON 配置");
  return readAccountInput(json!);
}

/** Structured input generated by the agent from the user's Chinese publication rules. */
export function readAccountInput(json: string): JsonRecord {
  const config = JSON.parse(json);
  check(config && typeof config === "object" && Array.isArray(config.accounts), "accounts 必须为数组");
  const names = new Map<string, string>();
  const ids = new Set<string>();
  for (const account of config.accounts) {
    check(typeof account.name === "string" && account.name.trim(), "账号实际名称不能为空");
    check(typeof account.id === "string" && account.id.trim() && !ids.has(account.id), "账号配置 id 缺失或重复");
    ids.add(account.id);
    check(
      Array.isArray(account.aliases) && account.aliases.every((v: unknown) => typeof v === "string" && v.trim()),
      "aliases 必须为非空字符串数组，可为空数组",
    );
    check(
      account.platforms && typeof account.platforms === "object" && !Array.isArray(account.platforms),
      "platforms 必须为平台映射",
    );
    for (const label of [account.name, ...account.aliases]) {
      const key = label.trim();
      check(
        !names.has(key) || names.get(key) === account.id,
        `账号名称或别名冲突：${key}；请使用唯一名称修正配置后再执行`,
      );
      names.set(key, account.id);
    }
  }
  check(
    typeof config.defaultAccount === "string" && names.has(config.defaultAccount.trim()),
    "默认账号未匹配配置中的名称或别名",
  );
  return config;
}

export function resolveAccount(config: JsonRecord, requested?: string, platforms: string[] = []): JsonRecord {
  const name = (requested ?? config.defaultAccount).trim();
  const matches = config.accounts.filter((a: JsonRecord) =>
    [a.name, ...a.aliases].some((n: string) => n.trim() === name),
  );
  check(matches.length === 1, matches.length ? "账号匹配不唯一，请明确选择账号" : `未配置账号：${name}`);
  const account = matches[0];
  check(platforms.length > 0, "须通过 --platforms 明确本次目标平台");
  const selected: JsonRecord = {};
  const pending: string[] = [];
  for (const platform of platforms) {
    const binding = account.platforms[platform];
    if (!binding || typeof binding !== "object") {
      pending.push(`${platform}：未配置账号映射`);
      continue;
    }
    for (const key of ["accountId", "nickname", "browser", "profile"]) {
      if (typeof binding[key] !== "string" || !binding[key].trim()) pending.push(`${platform}：缺少 ${key}`);
    }
    if (binding.browser && !["chrome", "edge"].includes(binding.browser))
      pending.push(`${platform}：browser 仅支持 chrome 或 edge`);
    selected[platform] = { ...binding };
  }
  return {
    status: pending.length ? "needs_attention" : "resolved",
    account: { id: account.id, name: account.name },
    selectionSource: requested === undefined ? "default" : "this_request",
    platforms: selected,
    pending,
    // Resolution is read-only; it proves neither executor selection nor logged-in identity.
    identityVerified: false,
  };
}
